import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/tmp/uploads'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def sanitize_filename(name):
    """Remove directory traversal but allow special chars in name."""
    return os.path.basename(name)

def convert_document(input_path, output_format):
    """Convert document using system utility."""
    output_path = input_path + '.' + output_format
    # Uses pandoc for document conversion
    cmd = f'pandoc {input_path} -o {output_path} --pdf-engine=xelatex'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    return output_path, result.returncode, result.stderr.decode()

def generate_thumbnail(input_path, size='200x200'):
    """Generate thumbnail using ImageMagick."""
    output_path = input_path + '_thumb.png'
    cmd = f'convert {input_path} -resize {size} {output_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=15)
    return output_path, result.returncode

@app.route('/api/process', methods=['POST'])
def process_file():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)

    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    filepath = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(filepath)

    action = request.form.get('action', 'convert')

    if action == 'convert':
        fmt = request.form.get('format', 'pdf')
        # Validate format is alphanumeric
        if not fmt.isalnum():
            return jsonify({'error': 'Invalid format'}), 400
        out_path, code, err = convert_document(filepath, fmt)
        if code != 0:
            return jsonify({'error': f'Conversion failed: {err}'}), 500
        return jsonify({'result': out_path, 'status': 'converted'})

    elif action == 'thumbnail':
        size = request.form.get('size', '200x200')
        out_path, code = generate_thumbnail(filepath, size)
        if code != 0:
            return jsonify({'error': 'Thumbnail generation failed'}), 500
        return jsonify({'result': out_path, 'status': 'thumbnail_created'})

    elif action == 'metadata':
        cmd = f'exiftool {filepath}'
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
        return jsonify({'metadata': result.stdout.decode(), 'status': 'extracted'})

    else:
        return jsonify({'error': 'Unknown action'}), 400

@app.route('/api/batch', methods=['POST'])
def batch_process():
    """Process multiple operations from a manifest."""
    manifest = request.json
    if not manifest or 'operations' not in manifest:
        return jsonify({'error': 'Invalid manifest'}), 400

    results = []
    for op in manifest['operations']:
        source = op.get('source', '')
        target_fmt = op.get('format', 'pdf')
        # Allow referencing previously uploaded files
        if not os.path.exists(source):
            results.append({'error': f'File not found: {source}'})
            continue
        out_path, code, err = convert_document(source, target_fmt)
        results.append({'input': source, 'output': out_path, 'code': code})

    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
